<script setup lang="ts">
import {computed,ref,shallowRef,watch,onMounted,onUnmounted,nextTick} from 'vue';
import Dialog from 'primevue/dialog';
import type {SummaryConsentProposal} from '../../shared/summary-automation';
import type {SummarySelectionRequest,SummaryReviewBridge,SummaryTransferProposal,SummaryRetryProposal} from '../../shared/summary-review';
import {createSummaryReviewState,selectionKey,type SummaryReviewState,type SummaryRunAuthority} from '../summary-review-state';
import SummaryStatusIcon from './SummaryStatusIcon.vue';
import SummaryTaskPicker from './SummaryTaskPicker.vue';
import SummaryResult from './SummaryResult.vue';
import GitMetadataReadSettings from './GitMetadataReadSettings.vue';
const props=defineProps<{workstreamId:string;projectTitle:string;blockedReason?:string|null}>();
const bridge=new Proxy({} as SummaryReviewBridge,{get:(_,key)=>(...args:unknown[])=>Reflect.apply(Reflect.get(window.noteApp,key),window.noteApp,args)});
const recent=createSummaryReviewState(bridge,{workstreamId:props.workstreamId,selection:{purpose:'recent'}});
const recentView=computed(()=>recent.view.value),recentRunning=computed(()=>recent.running.value);
const custom=shallowRef<SummaryReviewState|null>(null),selectedIds=ref<string[]>([]),pickerOpen=ref(false);
const customView=computed(()=>custom.value?.view.value??null),customRunning=computed(()=>custom.value?.running.value??false);
const selectionRequest=():SummarySelectionRequest=>({workstreamId:props.workstreamId,selection:{purpose:'custom',taskIds:[...selectedIds.value].sort()}});
const oldSelection=computed(()=>!!custom.value&&selectionKey(custom.value.request)!==selectionKey(selectionRequest()));
const metadataEditing=ref(false),metadataRecovery=ref(''),metadataMutationPending=ref(false);let metadataMutationSequence=0;
const metadataExecutionBlock=computed(()=>metadataRecovery.value?'로컬 읽기 허용의 복구·철회 상태를 먼저 확인해 주세요.':metadataMutationPending.value?'로컬 읽기 변경 상태를 확인한 뒤 요약할 수 있습니다.':'');
const settingsOpen=ref(false),settingsBusy=ref(false),settingsError=ref(''),proposal=shallowRef<SummaryConsentProposal|null>(null),remember=ref(false),autoEnabled=ref(false);
const pending=shallowRef<SummarySelectionRequest|null>(null),transfer=shallowRef<SummaryTransferProposal|null>(null);
const pickerTrigger=ref<HTMLButtonElement|null>(null),settingsTrigger=ref<HTMLButtonElement|null>(null),updateTrigger=ref<HTMLButtonElement|null>(null);
let settingsFocus:HTMLElement|null=null,settingsGeneration=0,disposed=false,polling=false,timer:ReturnType<typeof setTimeout>|undefined;
const recentLatest=computed(()=>recentView.value&&'latest' in recentView.value.model.latest?recentView.value.model.latest.latest:null);
const mainStatus=computed(()=>recentRunning.value?{kind:'info',label:'요약 중',shape:'progress'}:recent.error.value||recentView.value?.model.state==='failed'?{kind:'error',label:'요약 실패',shape:'alert'}:recentView.value?.model.latest.state==='stale'?{kind:'warning',label:'이전 결과 · 업데이트 필요',shape:'clock'}:recentLatest.value?{kind:'success',label:'저장된 AI 요약 · 내용 검수 필요',shape:'check'}:{kind:'muted',label:'요약 없음',shape:'unknown'});
const automatic=computed(()=>recentView.value?.automation);
const automaticStatus=computed(()=>{const state=automatic.value?.state??'off';return ({off:{kind:'muted',label:'자동 꺼짐',shape:'pause'},waiting:{kind:'info',label:'자동 업데이트 대기',shape:'clock'},running:{kind:'info',label:'자동 요약 중',shape:'progress'},limited:{kind:'warning',label:'실행 한도 대기',shape:'clock'},failed:{kind:'error',label:'자동 업데이트 실패',shape:'alert'},'needs-consent':{kind:'warning',label:'전송 허용 필요',shape:'unknown'},unavailable:{kind:'warning',label:'자동 업데이트 확인 필요',shape:'alert'},current:{kind:'success',label:'자동 업데이트 최신',shape:'check'}})[state];});
const automaticNext=computed(()=>automatic.value?.nextAt?new Date(automatic.value.nextAt).toLocaleString('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'}):null);
const settingsBinding=computed(()=>transfer.value?.binding??proposal.value?.binding??null);
const selectedSummary=computed(()=>pending.value?.selection.purpose==='custom'?pending.value.selection.taskIds?.join(' · '):'확인된 선언 기록의 최근 태스크 최대 3개');
function applyAutomation(value:NonNullable<typeof recentView.value>['automation']){if(recent.view.value)recent.view.value={...recent.view.value,automation:value};if(custom.value?.view.value)custom.value.view.value={...custom.value.view.value,automation:value};}
async function poll(){if(disposed||polling)return;polling=true;try{if(document.visibilityState!=='hidden'){await recent.refresh();if(pickerOpen.value&&custom.value)await custom.value.refresh();}}finally{polling=false;if(!disposed)timer=setTimeout(poll,recentRunning.value||customRunning.value?1200:4000);}}
function wake(){if(document.visibilityState==='visible'){if(timer)clearTimeout(timer);void poll();}}
onMounted(()=>{void poll();document.addEventListener('visibilitychange',wake);});
async function openPicker(){pickerOpen.value=true;if(!selectedIds.value.length)selectedIds.value=[...(recentView.value?.recent.taskIds??[])];await recent.refresh();}
async function openTasks(ids:string[]){selectedIds.value=[...new Set(ids)].slice(0,20);await openPicker();}
defineExpose({openTasks});
function closePicker(){pickerOpen.value=false;if(pending.value?.selection.purpose==='custom')closeSettings();if(retryRequest.value?.selection.purpose==='custom')void closeRetry();custom.value?.dispose();custom.value=null;void nextTick(()=>pickerTrigger.value?.focus({preventScroll:true}));}
async function prepareSettingsScope(){const own=++settingsGeneration,request=pending.value;proposal.value=null;settingsError.value='';settingsBusy.value=true;try{const next=await bridge.prepareSummaryConsent({workstreamId:props.workstreamId});if(disposed||own!==settingsGeneration||!settingsOpen.value)return;if(request){const ticket=await bridge.prepareSummaryTransfer(request);if(disposed||own!==settingsGeneration||!settingsOpen.value){await bridge.cancelSummaryTransfer({ticketId:ticket.ticketId});return;}if(JSON.stringify(ticket.binding)!==JSON.stringify(next.binding)||selectionKey({...request,selection:ticket.selection})!==selectionKey(request)){await bridge.cancelSummaryTransfer({ticketId:ticket.ticketId});throw Error('Consent binding changed');}transfer.value=ticket;}proposal.value=next;}catch{if(!disposed&&own===settingsGeneration)settingsError.value='전송 대상·계정·허용 경로를 확인하지 못했습니다. 연결과 요약 설정을 다시 확인해 주세요.';}finally{if(own===settingsGeneration)settingsBusy.value=false;}}
async function openSettings(request:SummarySelectionRequest|null=null){if(transfer.value)void bridge.cancelSummaryTransfer({ticketId:transfer.value.ticketId}).catch(()=>{});transfer.value=null;settingsFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;pending.value=request?structuredClone(request):null;remember.value=automatic.value?.remembered??false;autoEnabled.value=automatic.value?.autoEnabled??false;settingsOpen.value=true;await prepareSettingsScope();}
function metadataChanging(){settingsGeneration++;const ticket=transfer.value;transfer.value=null;proposal.value=null;settingsBusy.value=false;remember.value=false;autoEnabled.value=false;settingsError.value='로컬 읽기 변경 후 AI 전송 범위를 다시 확인해 주세요.';if(ticket)void bridge.cancelSummaryTransfer({ticketId:ticket.ticketId}).catch(()=>{});if(recentRunning.value)void recent.cancel();if(customRunning.value)void custom.value?.cancel();if(retryOpen.value)void closeRetry();}
async function trackMetadataMutation(completion:Promise<void>){const own=++metadataMutationSequence;metadataMutationPending.value=true;try{await completion;const state=await window.noteApp.getGitMetadataReadState({workstreamId:props.workstreamId});if(!disposed&&own===metadataMutationSequence)metadataRecovery.value=state.recoveryRequired?(state.error||'로컬 읽기 허용이 저장됐을 수 있습니다. 저장소 복구 후 허용 철회를 완료하기 전에 앱을 다시 시작하지 마세요.'):'';}catch{if(!disposed&&own===metadataMutationSequence)metadataRecovery.value='로컬 읽기 변경 결과를 확인하지 못했습니다. 앱을 다시 시작하기 전에 요약 설정에서 읽기 허용 상태를 확인해 주세요.';}finally{if(!disposed&&own===metadataMutationSequence)metadataMutationPending.value=false;}}
async function metadataChanged(){metadataChanging();const own=settingsGeneration;await Promise.all([recent.refresh(),custom.value?.refresh()]);if(disposed||own!==settingsGeneration||!settingsOpen.value)return;await prepareSettingsScope();}
function closeSettings(){const ticket=transfer.value;transfer.value=null;if(ticket)void bridge.cancelSummaryTransfer({ticketId:ticket.ticketId}).catch(()=>{});settingsOpen.value=false;settingsGeneration++;settingsBusy.value=false;proposal.value=null;pending.value=null;void nextTick(()=>{if(settingsFocus?.isConnected)settingsFocus.focus({preventScroll:true});});}
async function runRequest(request:SummarySelectionRequest,authority:SummaryRunAuthority){if(request.selection.purpose==='recent'){await recent.run(authority);return;}if(!pickerOpen.value)return;custom.value?.dispose();const next=createSummaryReviewState(bridge,request);custom.value=next;await next.run(authority);}
async function update(){if(metadataRecovery.value||metadataMutationPending.value||recentRunning.value||props.blockedReason||recentView.value?.recent.state!=='ready')return;const request:SummarySelectionRequest={workstreamId:props.workstreamId,selection:{purpose:'recent'}};if(automatic.value?.remembered&&!['needs-consent','unavailable'].includes(automatic.value.state))await runRequest(request,{useRememberedConsent:true});else await openSettings(request);}
async function summarizeSelected(){if(metadataRecovery.value||metadataMutationPending.value||customRunning.value||!selectedIds.value.length||selectedIds.value.length>20)return;await openSettings(selectionRequest());}
async function saveSettings(){const p=proposal.value,request=pending.value,ticket=transfer.value,own=settingsGeneration;if(!p||request&&!ticket||settingsBusy.value||metadataEditing.value||metadataRecovery.value||metadataMutationPending.value||autoEnabled.value&&!remember.value)return;settingsBusy.value=true;settingsError.value='';try{if(remember.value){const value=await bridge.confirmSummaryConsent({ticketId:p.ticketId,recurringTransferConfirmed:true,usageConfirmed:true,autoEnabled:autoEnabled.value});if(disposed||own!==settingsGeneration)return;applyAutomation(value);}else if(automatic.value?.remembered){const value=await bridge.revokeSummaryConsent({workstreamId:props.workstreamId});if(disposed||own!==settingsGeneration)return;applyAutomation(value);}if(disposed||own!==settingsGeneration)return;transfer.value=null;closeSettings();if(request&&ticket)await runRequest(request,{transferTicketId:ticket.ticketId});else await recent.refresh();}catch{if(!disposed&&own===settingsGeneration)settingsError.value='설정을 적용하지 못했습니다. 전송 범위를 다시 확인해 주세요.';}finally{if(own===settingsGeneration)settingsBusy.value=false;}}
async function revoke(){if(settingsBusy.value)return;const own=settingsGeneration;settingsBusy.value=true;try{const value=await bridge.revokeSummaryConsent({workstreamId:props.workstreamId});if(disposed||own!==settingsGeneration)return;applyAutomation(value);remember.value=false;autoEnabled.value=false;await recent.refresh();}catch{if(!disposed&&own===settingsGeneration)settingsError.value='권한 철회 상태를 확인하지 못했습니다. 다시 확인해 주세요.';}finally{if(own===settingsGeneration)settingsBusy.value=false;}}
async function disableAuto(){try{applyAutomation(await bridge.setSummaryAuto({workstreamId:props.workstreamId,enabled:false}));}catch{recent.error.value='자동 업데이트를 끄지 못했습니다. 요약 설정을 다시 확인해 주세요.';}}
watch(remember,value=>{if(!value)autoEnabled.value=false;});
const retryTicket=shallowRef<SummaryRetryProposal|null>(null),retryRequest=shallowRef<SummarySelectionRequest|null>(null),retryOpen=ref(false),retryBusy=ref(false),retryConfirmed=ref(false),retryError=ref('');let retryGeneration=0,retryFocus:HTMLElement|null=null;
async function openRetry(state:SummaryReviewState){if(metadataRecovery.value||metadataMutationPending.value)return;const own=++retryGeneration;retryRequest.value=structuredClone(state.request);retryFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;retryOpen.value=true;retryBusy.value=true;retryConfirmed.value=false;retryError.value='';try{const ticket=await bridge.prepareSummaryRetry(state.request);if(disposed||own!==retryGeneration){await bridge.cancelSummaryRetry({ticketId:ticket.ticketId});return;}retryTicket.value=ticket;}catch{if(!disposed&&own===retryGeneration)retryError.value='진단 재시도를 준비하지 못했습니다. 상태를 다시 확인해 주세요.';}finally{if(own===retryGeneration)retryBusy.value=false;}}
async function closeRetry(){retryGeneration++;const wasRunning=retryBusy.value&&!!retryTicket.value,request=retryRequest.value;retryOpen.value=false;retryBusy.value=false;retryConfirmed.value=false;const ticket=retryTicket.value;retryTicket.value=null;retryRequest.value=null;if(wasRunning&&request)await bridge.cancelSummarySelection(request).catch(()=>{});if(ticket)await bridge.cancelSummaryRetry({ticketId:ticket.ticketId}).catch(()=>{});void nextTick(()=>{if(retryFocus?.isConnected)retryFocus.focus({preventScroll:true});});}
async function runRetry(){const ticket=retryTicket.value,request=retryRequest.value,own=retryGeneration;if(metadataRecovery.value||metadataMutationPending.value||!ticket||!request||!retryConfirmed.value||retryBusy.value)return;retryBusy.value=true;try{const model=await bridge.runSummaryRetry({ticketId:ticket.ticketId,transferConfirmed:true,oneCallConfirmed:true});if(disposed||own!==retryGeneration)return;const state=request.selection.purpose==='recent'?recent:custom.value;if(state&&selectionKey(state.request)===selectionKey(request))state.acceptModel(model);retryTicket.value=null;await closeRetry();}catch{if(!disposed&&own===retryGeneration)retryError.value='진단 결과를 확인하지 못했습니다. 자동 재시도하지 않습니다.';}finally{if(own===retryGeneration)retryBusy.value=false;}}
watch([metadataRecovery,metadataMutationPending],([recovery,pending])=>{if((recovery||pending)&&(retryOpen.value||retryTicket.value||retryRequest.value))void closeRetry();},{flush:'sync'});
onUnmounted(()=>{disposed=true;if(timer)clearTimeout(timer);document.removeEventListener('visibilitychange',wake);settingsGeneration++;if(transfer.value)void bridge.cancelSummaryTransfer({ticketId:transfer.value.ticketId}).catch(()=>{});void closeRetry();recent.dispose();custom.value?.dispose();});
</script>
<template>
 <section class="summary-review-panel" data-testid="summary-review-panel">
  <header class="summary-card-heading"><div class="summary-title-status"><h3>최근 작업</h3><SummaryStatusIcon v-bind="mainStatus"/></div><div class="summary-inline-actions"><button ref="pickerTrigger" class="summary-button summary-primary" data-testid="summary-task-open" @click="openPicker">작업 선택 요약</button><button ref="updateTrigger" class="summary-button" data-testid="summary-update" :disabled="!!metadataRecovery||metadataMutationPending||recentRunning||!!blockedReason||recentView?.recent.state!=='ready'||recentView?.model.state==='disabled'" @click="update">업데이트</button><button ref="settingsTrigger" class="summary-button" data-testid="summary-settings-open" @click="openSettings()">요약 설정</button></div></header>
  <p v-if="recentLatest" class="summary-caption">마지막 요약 · {{new Date(recentLatest.generatedAt).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}}</p>
  <p v-if="recentView?.model.state==='disabled'" class="summary-state-message summary-warning" role="status">{{recentView.model.message}}</p>
  <p v-if="metadataMutationPending" class="summary-caption" role="status">로컬 읽기 변경 상태 확인 중</p>
  <div v-if="metadataRecovery" class="summary-state-message summary-error" role="alert" data-testid="summary-metadata-recovery"><p>{{metadataRecovery}}</p><button class="summary-text-button" @click="openSettings()">읽기 상태 확인</button></div>
  <p v-if="blockedReason" class="summary-state-message summary-warning" role="alert">{{blockedReason}} 프로젝트 설정에서 연결을 확인해 주세요.</p>
  <div v-if="automatic" class="summary-auto-state" :class="{'summary-inline-warning':['failed','limited','needs-consent','unavailable'].includes(automatic.state)}" role="status" aria-live="polite" data-testid="summary-auto-state"><SummaryStatusIcon v-bind="automaticStatus"/><span>{{automaticStatus.label}}<template v-if="automaticNext&&['limited','waiting'].includes(automatic.state)"> · {{automaticNext}} 이후</template></span><button v-if="['failed','needs-consent','unavailable'].includes(automatic.state)" class="summary-text-button" @click="openSettings()">설정 확인</button><button v-if="automatic.autoEnabled" class="summary-text-button" @click="disableAuto">자동 끄기</button></div>
  <SummaryResult data-testid="summary-recent-result" :model="recentView?.model??null" :recent="recentView?.recent" :running="recentRunning" :retry-disabled="!!metadataExecutionBlock" :error="recent.error.value" @refresh="recent.refresh" @retry="openRetry(recent)" @settings="openSettings()" @select="openPicker" @cancel="recent.cancel"/>
 </section>
 <Dialog :visible="pickerOpen" modal header="작업 선택 요약" class="summary-dialog summary-task-dialog" data-testid="summary-task-dialog" :style="{width:'1060px',maxWidth:'calc(100vw - 40px)'}" @update:visible="value=>{if(!value)closePicker()}" @after-hide="pickerTrigger?.focus({preventScroll:true})">
  <p class="summary-caption summary-dialog-project">{{projectTitle}}</p><p v-if="metadataExecutionBlock" class="summary-inline-warning" role="status" data-testid="summary-picker-metadata-block">{{metadataExecutionBlock}}</p><div class="summary-selection-layout"><SummaryTaskPicker v-model="selectedIds" :tasks="recentView?.tasks??[]" :disabled="customRunning||!!metadataExecutionBlock" @run="summarizeSelected"/><div class="summary-selection-result" data-testid="summary-custom-result"><SummaryResult :model="customView?.model??null" :task-ids="custom?.request.selection.taskIds" :old-selection="oldSelection" :running="customRunning" :retry-disabled="!!metadataExecutionBlock" :error="custom?.error.value" show-heading @refresh="custom?.refresh()" @retry="custom&&openRetry(custom)" @settings="openSettings()" @cancel="custom?.cancel()"/></div></div>
 </Dialog>
 <Dialog :visible="settingsOpen" modal header="요약 설정" class="summary-dialog summary-settings-dialog" data-testid="summary-settings-dialog" :style="{width:'830px',maxWidth:'calc(100vw - 40px)'}" @update:visible="value=>{if(!value)closeSettings()}">
  <div class="summary-settings-content"><GitMetadataReadSettings :workstream-id="workstreamId" :active="settingsOpen" :disabled="settingsBusy" @editing="metadataEditing=$event" @changing="metadataChanging" @changed="metadataChanged" @recovery="metadataRecovery=$event" @tracking="trackMetadataMutation"/><p v-if="settingsBusy&&!proposal" role="status">전송 범위를 확인 중입니다</p><p v-if="settingsError" class="summary-state-message summary-error" role="alert">{{settingsError}}</p>
   <button v-if="!proposal&&!settingsBusy" class="summary-button" data-testid="summary-scope-refresh" :disabled="metadataEditing||metadataMutationPending||!!metadataRecovery" @click="prepareSettingsScope">AI 전송 범위 다시 확인</button>
   <template v-if="settingsBinding"><h4>AI 전송 설정</h4><dl class="summary-settings-facts"><div><dt>프로젝트</dt><dd>{{projectTitle}}</dd></div><div><dt>전송 대상</dt><dd>{{settingsBinding.provider}} · {{settingsBinding.accountLabel}}<small>정책 {{settingsBinding.modelPolicy}}</small><details class="summary-account-identity"><summary>계정 식별자</summary><small>{{settingsBinding.accountId}}</small></details></dd></div><div><dt>자료</dt><dd>{{selectedSummary}} · DAG · 연결 문서 발췌</dd></div><div><dt>허용 경로</dt><dd><span v-for="root in settingsBinding.roots" :key="root.identity" class="summary-root">{{root.path}}</span><small>명시 허용된 연결 Markdown · 소스 코드 본문 제외</small></dd></div></dl>
    <label class="summary-check"><input v-model="remember" type="checkbox" data-testid="summary-remember" :disabled="settingsBusy||metadataEditing"/><strong>이 프로젝트의 전송 권한 기억하기</strong></label>
    <label class="summary-check"><input v-model="autoEnabled" type="checkbox" data-testid="summary-auto-enabled" :disabled="settingsBusy||metadataEditing||!remember"/><strong>창이 보이고 포커스가 있을 때 자동 업데이트</strong></label>
    <p class="summary-caption summary-check-help">기억되는 범위: 확인된 선언 기록의 최근 태스크 최대 3개 · 대상 작업은 바뀔 수 있습니다. 선택 작업은 매번 직접 확인합니다.</p>
    <dl class="summary-settings-limits"><div><dt>실행 한도</dt><dd>10초 대기 · 2분 간격 · 시간당 최대 6회</dd></div><div><dt>모델 호출</dt><dd>실행당 최대 2회 · {{settingsBinding.provider}} 사용량 소모</dd></div><div><dt>작업 선택</dt><dd>다이얼로그에서 직접 실행</dd></div></dl>
    <p class="summary-state-message summary-warning">비밀키·토큰·인증 파일은 제외합니다. 민감정보 차단은 완전하지 않습니다.</p><p class="summary-caption">로컬 읽기 허용과 AI 전송 동의는 별도입니다. 범위 변경 시 재확인합니다.</p>
    <div v-if="automatic?.remembered" class="summary-inline-actions"><button class="summary-text-button" data-testid="summary-revoke" :disabled="settingsBusy||metadataEditing" @click="revoke">전송 권한 철회</button><span class="summary-caption">언제든 자동 업데이트를 끄거나 철회할 수 있습니다</span></div>
   </template>
  </div>
  <template #footer><button class="summary-button" @click="closeSettings">취소</button><button class="summary-button summary-primary" data-testid="summary-consent-confirm" :disabled="!proposal||settingsBusy||metadataEditing||!!metadataRecovery||metadataMutationPending||autoEnabled&&!remember" @click="saveSettings">{{pending?'허용하고 시작':'설정 저장'}}</button></template>
 </Dialog>
 <Dialog :visible="retryOpen" data-testid="summary-retry-dialog" modal header="실패 진단 1회" class="summary-dialog" :style="{width:'720px',maxWidth:'calc(100vw - 40px)'}" @update:visible="value=>{if(!value)closeRetry()}"><div class="summary-settings-content"><p>{{projectTitle}}</p><p v-if="retryTicket">{{retryTicket.transferBinding.provider}} · {{retryTicket.transferBinding.accountLabel}}<br>{{retryTicket.transferBinding.modelPolicy}}</p><details v-if="retryTicket" class="summary-account-identity"><summary>계정 식별자</summary><p>{{retryTicket.transferBinding.accountId}}</p></details><p v-if="retryTicket">허용 경로: {{retryTicket.transferBinding.roots.map(r=>r.path).join(' · ')}}</p><p>현재 실패 입력을 추가 1회 전송합니다. 사용량이 소모되며 형식 수정·자동 재호출은 없습니다. 기존 성공 본문은 바꾸지 않습니다.</p><p v-if="retryTicket" class="summary-caption">실패 입력 {{retryTicket.inputHash}}</p><p v-if="retryBusy" role="status">진단 확인 중</p><p v-if="retryError" class="summary-state-message summary-error" role="alert">{{retryError}}</p><label class="summary-check"><input v-model="retryConfirmed" type="checkbox" :disabled="retryBusy||!!metadataExecutionBlock" data-testid="summary-retry-confirm"/>전송 범위와 추가 호출 1회를 확인했습니다</label></div><template #footer><button class="summary-button" @click="closeRetry">취소</button><button class="summary-button summary-primary" data-testid="summary-retry-run" :disabled="!retryTicket||!retryConfirmed||retryBusy||!!metadataExecutionBlock" @click="runRetry">진단 1회 실행</button></template></Dialog>
</template>
